IF SCHEMA_ID('oltp') IS NULL EXEC('CREATE SCHEMA oltp');
IF OBJECT_ID('oltp.Region') IS NULL CREATE TABLE oltp.Region(id_region int IDENTITY PRIMARY KEY,nombre nvarchar(150) NOT NULL UNIQUE);
IF OBJECT_ID('oltp.Provincia') IS NULL CREATE TABLE oltp.Provincia(id_provincia int IDENTITY PRIMARY KEY,id_region int NOT NULL REFERENCES oltp.Region(id_region),nombre nvarchar(150) NOT NULL,UNIQUE(id_region,nombre));
IF OBJECT_ID('oltp.Distrito') IS NULL CREATE TABLE oltp.Distrito(id_distrito int IDENTITY PRIMARY KEY,id_provincia int NOT NULL REFERENCES oltp.Provincia(id_provincia),ubigeo nvarchar(20) NOT NULL,nombre nvarchar(150) NOT NULL,UNIQUE(id_provincia,ubigeo,nombre));
IF OBJECT_ID('oltp.Unidad_Ejecutora') IS NULL CREATE TABLE oltp.Unidad_Ejecutora(id_unidad int IDENTITY PRIMARY KEY,clave_version binary(32) NOT NULL UNIQUE,codigo nvarchar(50) NOT NULL,nombre nvarchar(400) NOT NULL);
IF OBJECT_ID('oltp.IPRESS') IS NULL CREATE TABLE oltp.IPRESS(id_ipress int IDENTITY PRIMARY KEY,clave_version binary(32) NOT NULL UNIQUE,cod_ipress nvarchar(50) NOT NULL,nombre nvarchar(400) NOT NULL,nivel nvarchar(50) NOT NULL,id_distrito int NOT NULL REFERENCES oltp.Distrito(id_distrito),id_unidad int NOT NULL REFERENCES oltp.Unidad_Ejecutora(id_unidad),ubigeo_valido bit NOT NULL);
IF OBJECT_ID('oltp.Servicio') IS NULL CREATE TABLE oltp.Servicio(id_servicio int IDENTITY PRIMARY KEY,clave_version binary(32) NOT NULL UNIQUE,codigo nvarchar(50) NOT NULL,descripcion nvarchar(400) NOT NULL);
IF OBJECT_ID('oltp.Plan_Seguro') IS NULL CREATE TABLE oltp.Plan_Seguro(id_plan int IDENTITY PRIMARY KEY,nombre nvarchar(100) NOT NULL UNIQUE);
IF OBJECT_ID('oltp.Sexo') IS NULL CREATE TABLE oltp.Sexo(id_sexo int IDENTITY PRIMARY KEY,nombre nvarchar(50) NOT NULL UNIQUE);
IF OBJECT_ID('oltp.Grupo_Edad') IS NULL CREATE TABLE oltp.Grupo_Edad(id_grupo_edad int IDENTITY PRIMARY KEY,nombre nvarchar(100) NOT NULL UNIQUE);
IF OBJECT_ID('oltp.Registro_Atencion') IS NULL CREATE TABLE oltp.Registro_Atencion(id_registro_atencion bigint IDENTITY PRIMARY KEY,archivo nvarchar(260) NOT NULL,fila_archivo bigint NOT NULL,anio int NOT NULL,mes int NOT NULL,id_ipress int NOT NULL REFERENCES oltp.IPRESS(id_ipress),id_servicio int NOT NULL REFERENCES oltp.Servicio(id_servicio),id_plan int NOT NULL REFERENCES oltp.Plan_Seguro(id_plan),id_sexo int NOT NULL REFERENCES oltp.Sexo(id_sexo),id_grupo_edad int NOT NULL REFERENCES oltp.Grupo_Edad(id_grupo_edad),cantidad_atenciones bigint NOT NULL CHECK(cantidad_atenciones>=0),fuente_tipo varchar(10) NOT NULL,clave_origen nvarchar(100) NULL,version_origen int NULL,id_raw bigint NOT NULL UNIQUE,UNIQUE(archivo,fila_archivo));
IF OBJECT_ID('oltp.OrigenVersion') IS NULL CREATE TABLE oltp.OrigenVersion(clave_origen nvarchar(100) PRIMARY KEY,version int NOT NULL,eliminado bit NOT NULL);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('oltp.Registro_Atencion') AND name='IX_Periodo') CREATE INDEX IX_Periodo ON oltp.Registro_Atencion(anio,mes) INCLUDE(cantidad_atenciones,fuente_tipo);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('oltp.Registro_Atencion') AND name='UX_Origen_SQL') CREATE UNIQUE INDEX UX_Origen_SQL ON oltp.Registro_Atencion(clave_origen) WHERE fuente_tipo='SQL';

IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name='CK_Registro_Periodo') ALTER TABLE oltp.Registro_Atencion WITH CHECK ADD CONSTRAINT CK_Registro_Periodo CHECK(anio BETWEEN 1900 AND 2100 AND mes BETWEEN 1 AND 12);
